-- Loan installments of posted loans by status, split active staff / leavers. Columns: st, who, n, stf, amt, coll
-- Status P paid, R rescheduled (replaced by later installments), N pending. Only N is still owed. Confirm the meaning at each new site.
SELECT i.INSTALLMENT_STATUS ST, CASE WHEN a.STAFF_ID IS NULL THEN 'LEAVER' ELSE 'ACTIVE' END WHO, COUNT(*) N, COUNT(DISTINCT l.STAFF_ID) STF, ROUND(SUM(i.INSTALLMENT_AMOUNT)) AMT, ROUND(SUM(NVL(i.COLLECTION_AMOUNT,0))) COLL FROM {P}PR_STAFF_LOANS_INSTALLMENTS i JOIN {P}PR_STAFF_LOANS l ON l.LOAN_ID=i.LOAN_ID LEFT JOIN (SELECT DISTINCT STAFF_ID FROM {P}PS_STAFF_CONTRACT WHERE STATUS='A' AND CURRENT_CONTRACT='Y') a ON a.STAFF_ID=l.STAFF_ID WHERE l.LOAN_STATUS='P' GROUP BY i.INSTALLMENT_STATUS, CASE WHEN a.STAFF_ID IS NULL THEN 'LEAVER' ELSE 'ACTIVE' END ORDER BY 2,1
